import numpy as np
# W: the reference path, 4,097 values (provided)

def quadratic_variation(W, step):
    """Sum of squared increments of W[::step]."""
    d = np.diff(W[::step])
    return float(np.sum(d ** 2))

def total_variation(W, step):
    """Sum of |increments| of W[::step]."""
    d = np.diff(W[::step])
    return float(np.sum(np.abs(d)))

def qv_table(W, ms):
    """Quadratic variation at m steps, for each m."""
    n = len(W) - 1
    return [quadratic_variation(W, n // m) for m in ms]
